--- glb-check.html	
+++ glb-check.html	
@@ -0,0 +1,30 @@
+<!doctype html><html><head><meta charset="utf-8"/><style>html,body{margin:0;height:100%;background:#181c22;color:#fff;font-family:monospace}#info{position:fixed;top:8px;left:8px;background:#000a;padding:8px;border-radius:8px;font-size:12px;white-space:pre-wrap}</style>
+<script type="importmap">{"imports":{"three":"https://unpkg.com/three@0.160.0/build/three.module.js","three/addons/":"https://unpkg.com/three@0.160.0/examples/jsm/"}}</script></head>
+<body><div id="info">loading…</div>
+<script type="module">
+import * as THREE from 'three';
+import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
+const renderer = new THREE.WebGLRenderer({antialias:true});
+renderer.setSize(innerWidth, innerHeight);
+renderer.toneMapping = THREE.ACESFilmicToneMapping;
+document.body.appendChild(renderer.domElement);
+const scene = new THREE.Scene(); scene.background = new THREE.Color(0x181c22);
+scene.add(new THREE.HemisphereLight(0xffffff, 0x334455, 1.2));
+const d = new THREE.DirectionalLight(0xffffff, 2); d.position.set(5,10,7); scene.add(d);
+const camera = new THREE.PerspectiveCamera(45, innerWidth/innerHeight, 0.01, 500);
