// ball (big, RL-style: light shell, dark pentagon patches in offset rows + seam shading)
function ballTexture(){const cv=document.createElement('canvas');cv.width=cv.height=256;const x=cv.getContext('2d');
 x.fillStyle='#eef1f4';x.fillRect(0,0,256,256);
 x.strokeStyle='rgba(120,140,160,.4)';x.lineWidth=2;
 for(let i=0;i<=256;i+=32){x.beginPath();x.moveTo(i,0);x.lineTo(i,256);x.stroke();x.beginPath();x.moveTo(0,i);x.lineTo(256,i);x.stroke();}
 function pent(cx,cy,r){x.beginPath();for(let i=0;i<5;i++){const a=-Math.PI/2+i*2*Math.PI/5;const px=cx+Math.cos(a)*r,py=cy+Math.sin(a)*r;i?x.lineTo(px,py):x.moveTo(px,py);}x.closePath();x.fill();}
 x.fillStyle='#16233c';
 const rows=[[32,0],[96,32],[160,0],[224,32]];
 for(const [yy,off] of rows){for(let xx=off;xx<256;xx+=64){pent(xx+16,yy,24);}}
 const t=new THREE.CanvasTexture(cv);return t;}

