let jumpQueued=false;addEventListener('keydown',e=>{if(e.code==='Space'&&!e.repeat)jumpQueued=true;});
// WebAudio: engine hum + boost noise + event blips + goal horn (created on first click)
let AC=null,engineOsc=null,engineGain=null,boostGain=null;
function initAudio(){if(AC){AC.resume&&AC.resume();return;}try{
 AC=new (window.AudioContext||window.webkitAudioContext)();
 engineOsc=AC.createOscillator();engineOsc.type='sawtooth';engineOsc.frequency.value=55;
 const f=AC.createBiquadFilter();f.type='lowpass';f.frequency.value=380;
 engineGain=AC.createGain();engineGain.gain.value=0;
 engineOsc.connect(f);f.connect(engineGain);engineGain.connect(AC.destination);engineOsc.start();
 const nb=AC.createBuffer(1,AC.sampleRate,AC.sampleRate);const ch=nb.getChannelData(0);
 for(let i=0;i<ch.length;i++)ch[i]=Math.random()*2-1;
 const ns=AC.createBufferSource();ns.buffer=nb;ns.loop=true;
 const bp=AC.createBiquadFilter();bp.type='bandpass';bp.frequency.value=900;bp.Q.value=0.7;
 boostGain=AC.createGain();boostGain.gain.value=0;
 ns.connect(bp);bp.connect(boostGain);boostGain.connect(AC.destination);ns.start();
}catch(e){AC=null;}}
function blip(freq,dur,type,vol,slide){if(!AC)return;try{
 const o=AC.createOscillator(),g=AC.createGain();o.type=type||'sine';
 o.frequency.setValueAtTime(freq,AC.currentTime);
 if(slide)o.frequency.exponentialRampToValueAtTime(Math.max(30,freq+slide),AC.currentTime+dur);
 g.gain.setValueAtTime(vol||0.18,AC.currentTime);g.gain.exponentialRampToValueAtTime(0.001,AC.currentTime+dur);
 o.connect(g);g.connect(AC.destination);o.start();o.stop(AC.currentTime+dur+0.03);}catch(e){}}
function horn(){if(!AC)return;[220,277,330,440].forEach((f,i)=>setTimeout(()=>blip(f,0.35,'square',0.15),i*140));}

